"""Persistent (copy-on-write) ordered containers used by the scheduler.

The branchable engine has to snapshot and restore its *entire* computational
state in constant time, therefore no queue may be represented by a mutable
container: every mutation copies only the nodes on the search path and all
other nodes stay shared with the previous versions.  Checkpoints are then
simply references to a root, and a restore is a pointer assignment.

Two container flavours are provided:

``ByteNode`` tree
    Ordered by an arbitrary comparable key, carrying the number of packets and
    their total byte weight in every subtree.  It backs the per-bank staging
    FIFOs (ordered by arrival ordinal) and the per-bank PIFOs (ordered by
    ``(rank, ordinal)``).

``LiveNode`` tree
    Ordered by ``(rank, ordinal)`` and carrying the number of live packets plus
    the *lag* accounting of every resident.  Lag increments are range updates
    ("every resident with a strictly smaller rank gains one"), which are
    realised with lazy propagation so that a service opportunity never has to
    touch the backlog.
"""

MASK64 = (1 << 64) - 1


class Priorities:
    """Deterministic pseudo random priority source (xorshift style LCG)."""

    __slots__ = ('_state',)

    def __init__(self, seed=0x2545F4914F6CDD1D):
        self._state = seed & MASK64

    def next(self):
        state = (self._state * 6364136223846793005 + 1442695040888963407) & MASK64
        self._state = state
        return state


# ---------------------------------------------------------------------------
# byte weighted ordered container
# ---------------------------------------------------------------------------


class ByteNode:
    __slots__ = ('key', 'prio', 'left', 'right', 'size', 'bsum', 'pkt')

    def __init__(self, key, prio, pkt, left, right, size, bsum):
        self.key = key
        self.prio = prio
        self.left = left
        self.right = right
        self.size = size
        self.bsum = bsum
        self.pkt = pkt


def _bsum(node):
    return node.bsum if node is not None else 0


def _size(node):
    return node.size if node is not None else 0


def byte_size(root):
    return _size(root)


def byte_bytes(root):
    return _bsum(root)


def _bmk(key, prio, pkt, left, right):
    return ByteNode(key, prio, pkt, left, right,
                    1 + _size(left) + _size(right),
                    pkt.length + _bsum(left) + _bsum(right))


def byte_insert(root, key, pkt, prio):
    """Insert ``pkt`` under ``key``; returns the new root."""
    if root is None:
        return ByteNode(key, prio, pkt, None, None, 1, pkt.length)
    if key < root.key:
        left = byte_insert(root.left, key, pkt, prio)
        if left.prio > root.prio:
            middle = left.right
            newright = _bmk(root.key, root.prio, root.pkt, middle, root.right)
            return _bmk(left.key, left.prio, left.pkt, left.left, newright)
        return _bmk(root.key, root.prio, root.pkt, left, root.right)
    right = byte_insert(root.right, key, pkt, prio)
    if right.prio > root.prio:
        middle = right.left
        newleft = _bmk(root.key, root.prio, root.pkt, root.left, middle)
        return _bmk(right.key, right.prio, right.pkt, newleft, right.right)
    return _bmk(root.key, root.prio, root.pkt, root.left, right)


def byte_append(root, key, pkt, prio):
    """Insert a key that is larger than every key already present."""
    if root is None:
        return ByteNode(key, prio, pkt, None, None, 1, pkt.length)
    if root.prio > prio:
        return _bmk(root.key, root.prio, root.pkt, root.left,
                    byte_append(root.right, key, pkt, prio))
    return _bmk(key, prio, pkt, byte_merge(root, None), None)


def byte_merge(left, right):
    """Concatenate two trees whose keys are strictly ordered."""
    if left is None:
        return right
    if right is None:
        return left
    if left.prio > right.prio:
        return _bmk(left.key, left.prio, left.pkt, left.left,
                    byte_merge(left.right, right))
    return _bmk(right.key, right.prio, right.pkt,
                byte_merge(left, right.left), right.right)


def byte_delete(root, key):
    """Remove ``key``; returns the new root (unchanged when absent)."""
    if root is None:
        return None
    if key < root.key:
        return _bmk(root.key, root.prio, root.pkt,
                    byte_delete(root.left, key), root.right)
    if key > root.key:
        return _bmk(root.key, root.prio, root.pkt,
                    root.left, byte_delete(root.right, key))
    return byte_merge(root.left, root.right)


def byte_find(root, key):
    while root is not None:
        if key == root.key:
            return root
        root = root.left if key < root.key else root.right
    return None


def byte_pop_min(root):
    """Remove and return the smallest entry: ``(node, new_root)``."""
    if root.left is None:
        return root, root.right
    node, left = byte_pop_min(root.left)
    return node, _bmk(root.key, root.prio, root.pkt, left, root.right)


def byte_split_count(root, count):
    """Split into the first ``count`` keys and the remainder."""
    if root is None:
        return None, None
    leftsize = _size(root.left)
    if count <= leftsize:
        first, rest = byte_split_count(root.left, count)
        return first, _bmk(root.key, root.prio, root.pkt, rest, root.right)
    first, rest = byte_split_count(root.right, count - leftsize - 1)
    return _bmk(root.key, root.prio, root.pkt, root.left, first), rest


def _byte_split_budget(root, budget):
    """Split off the longest prefix whose byte weight fits into ``budget``.

    Returns ``(kept_root, evicted_nodes_in_ascending_key_order)``.
    """
    if root is None:
        return None, []
    leftbytes = _bsum(root.left)
    if leftbytes + root.pkt.length <= budget:
        kept_right, evicted = _byte_split_budget(root.right,
                                                 budget - leftbytes - root.pkt.length)
        return _bmk(root.key, root.prio, root.pkt, root.left, kept_right), evicted
    kept_left, evicted = _byte_split_budget(root.left, budget)
    return kept_left, evicted + [root] + byte_inorder(root.right)


def byte_split_budget(root, budget):
    """Public wrapper of :func:`_byte_split_budget`."""
    kept, evicted = _byte_split_budget(root, budget)
    evicted.reverse()
    return kept, evicted


def byte_inorder(root):
    """Return the entries in ascending key order."""
    out = []
    stack = []
    node = root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        out.append(node)
        node = node.right
    return out


# ---------------------------------------------------------------------------
# live resident container with lag accounting
# ---------------------------------------------------------------------------


class LiveNode:
    __slots__ = ('key', 'prio', 'left', 'right', 'size', 'val', 'lazy',
                 'pkt', 'bank')

    def __init__(self, key, prio, pkt, bank, left, right, size, val, lazy):
        self.key = key
        self.prio = prio
        self.left = left
        self.right = right
        self.size = size
        self.val = val
        self.lazy = lazy
        self.pkt = pkt
        self.bank = bank


def _lmk(key, prio, pkt, bank, left, right, val, lazy):
    return LiveNode(key, prio, pkt, bank, left, right,
                    1 + _size(left) + _size(right), val, lazy)


def _lapply(node, delta):
    """Add ``delta`` to the lag of every resident of the subtree."""
    if node is None:
        return None
    return _lmk(node.key, node.prio, node.pkt, node.bank, node.left, node.right,
                node.val + delta, node.lazy + delta)


def live_size(root):
    return _size(root)


def live_insert(root, key, pkt, bank, prio, acc=0):
    """Insert a resident.

    ``acc`` accumulates the lazy increments carried by the ancestors of the
    insertion point; the new resident starts with a lag of exactly zero even
    when those increments exist.
    """
    if root is None:
        return LiveNode(key, prio, pkt, bank, None, None, 1, -acc, 0)
    acc += root.lazy
    if key < root.key:
        left = live_insert(root.left, key, pkt, bank, prio, acc)
        if left.prio > root.prio:
            middle = left.right
            newright = _lmk(root.key, root.prio, root.pkt, root.bank, middle,
                            root.right, root.val, root.lazy)
            return _lmk(left.key, left.prio, left.pkt, left.bank, left.left,
                        newright, left.val, left.lazy)
        return _lmk(root.key, root.prio, root.pkt, root.bank, left, root.right,
                    root.val, root.lazy)
    right = live_insert(root.right, key, pkt, bank, prio, acc)
    if right.prio > root.prio:
        middle = right.left
        newleft = _lmk(root.key, root.prio, root.pkt, root.bank, root.left,
                       middle, root.val, root.lazy)
        return _lmk(right.key, right.prio, right.pkt, right.bank, newleft,
                    right.right, right.val, right.lazy)
    return _lmk(root.key, root.prio, root.pkt, root.bank, root.left, right,
                root.val, root.lazy)


def live_merge(left, right):
    if left is None:
        return right
    if right is None:
        return left
    if left.prio > right.prio:
        return _lmk(left.key, left.prio, left.pkt, left.bank, left.left,
                    live_merge(left.right, right), left.val, left.lazy)
    return _lmk(right.key, right.prio, right.pkt, right.bank,
                live_merge(left, right.left), right.right, right.val, right.lazy)


def live_delete(root, key, acc=0):
    """Remove a resident.

    Returns ``(new_root, removed_node_or_None, lag_of_removed_node)``.
    """
    if root is None:
        return None, None, 0
    if key < root.key:
        newleft, node, lag = live_delete(root.left, key, acc + root.lazy)
        if node is None:
            return root, None, 0
        return (_lmk(root.key, root.prio, root.pkt, root.bank, newleft,
                     root.right, root.val, root.lazy), node, lag)
    if key > root.key:
        newright, node, lag = live_delete(root.right, key, acc + root.lazy)
        if node is None:
            return root, None, 0
        return (_lmk(root.key, root.prio, root.pkt, root.bank, root.left,
                     newright, root.val, root.lazy), node, lag)
    lag = root.val + acc
    left = _lapply(root.left, root.lazy)
    right = _lapply(root.right, root.lazy)
    return live_merge(left, right), root, lag


def live_find(root, key):
    """Locate a resident: ``(node_or_None, lag)``."""
    acc = 0
    while root is not None:
        if key == root.key:
            return root, root.val + acc
        acc += root.lazy
        root = root.left if key < root.key else root.right
    return None, 0


def live_count_below(root, rank):
    """Number of residents whose rank is strictly smaller than ``rank``."""
    total = 0
    while root is not None:
        if root.key[0] < rank:
            total += _size(root.left) + 1
            root = root.right
        else:
            root = root.left
    return total


def live_add_lag_below(root, rank):
    """Give every resident with a strictly smaller rank one lag unit."""
    if root is None:
        return None
    if root.key[0] < rank:
        # the whole left subtree has a smaller rank as well
        return _lmk(root.key, root.prio, root.pkt, root.bank,
                    _lapply(root.left, 1),
                    live_add_lag_below(root.right, rank),
                    root.val + 1, root.lazy)
    return _lmk(root.key, root.prio, root.pkt, root.bank,
                live_add_lag_below(root.left, rank), root.right,
                root.val, root.lazy)


def live_collect(root, acc=0, out=None):
    """Collect ``(packet_id, lag)`` pairs of every resident."""
    if out is None:
        out = []
    if root is None:
        return out
    stack = [(root, acc)]
    while stack:
        node, ancestors = stack.pop()
        below = ancestors + node.lazy
        if node.left is not None:
            stack.append((node.left, below))
        if node.right is not None:
            stack.append((node.right, below))
        out.append((node.pkt.pktid, node.val + ancestors))
    return out
